  //   cmd_stop               0 -> 44 -> 9 -> 13 -> 41 -> 45 -> 0  (6 ticks)
  //   cmd_start              0 -> 4 -> 32 -> 36 -> 1 -> 5 -> 33 -> 37 -> 8 -> 12 -> 40 -> 0  (11 ticks)
  //   cmd_bit_sda_released   0 -> 7 -> 35 -> 39 -> 10 -> 14 -> 0  (6 ticks)
  //   cmd_bit_sda_low        0 -> 2 -> 6 -> 34 -> 54 -> 19 -> 0  (6 ticks)
